"""Install the full-ref capture around the recognized Plugins prek shim."""

import argparse
import hashlib
import os
import re
import stat
import subprocess
import tempfile
from pathlib import Path

REFS = "HZ_PLUGINS_PUSH_REFS_FILE"
SCOPE = "HZ_PLUGINS_DIAGNOSTIC_SHA"
RUN = 'exec "$PREK" hook-impl --hook-dir "$HERE" --script-version 4 --hook-type=pre-push -- "$@"\n'
SHIM = (
    """#!/bin/sh
# File generated by prek: https://github.com/j178/prek
# ID: 182c10f181da4464a3eec51b83331688

HERE="$(cd "$(dirname "$0")" && pwd)"
PREK="{runner}"

# Check if the full path to prek is executable, otherwise fallback to PATH
if [ ! -x "$PREK" ]; then
    PREK="prek"
fi

"""
    + RUN
    + "\n"
)
STOCK = re.compile(re.escape(SHIM).replace(re.escape("{runner}"), r"/[A-Za-z0-9_./ @+-]+"))
CAPTURE = r"""# Preserve all Git ref updates before prek selects its first range.
unset HZ_PLUGINS_PUSH_REFS_FILE
push_dir="$(umask 077; mktemp -d "${TMPDIR:-/tmp}/hz-plugins-push.XXXXXX")" || exit 1
trap 'rm -f -- "$push_dir/refs" "$push_dir/checked"; rmdir -- "$push_dir"' EXIT
trap 'exit 1' HUP INT TERM
HZ_PLUGINS_PUSH_REFS_FILE="$push_dir/refs"
(umask 077; cat > "$HZ_PLUGINS_PUSH_REFS_FILE") || exit 1
export HZ_PLUGINS_PUSH_REFS_FILE
if [ -n "${HZ_PLUGINS_DIAGNOSTIC_SHA:-}" ]; then
    python3 scripts/presentation_push.py admit "$@" || exit $?
fi
"$PREK" hook-impl --hook-dir "$HERE" --script-version 4 --hook-type=pre-push -- "$@" \
    < "$HZ_PLUGINS_PUSH_REFS_FILE" || exit $?
if [ -n "${HZ_PLUGINS_DIAGNOSTIC_SHA:-}" ] && [ ! -f "$push_dir/checked" ]; then
    echo "The ordinary hook did not run the diagnostic checks." >&2
    exit 1
fi
"""


def stock_source(source: str) -> str:
    original = source.replace(CAPTURE, RUN, 1)
    if not STOCK.fullmatch(original):
        raise ValueError("The installed pre-push is not a recognized prek shim.")
    return original


def hook_path() -> Path:
    """Use Git's ordinary shared hook directory and reject an override."""
    if (
        subprocess.run(
            ["git", "config", "--get-all", "core.hooksPath"], stdout=subprocess.DEVNULL, check=False, timeout=30
        ).returncode
        != 1
    ):
        raise ValueError("Use the ordinary Git hook directory.")
    common = subprocess.check_output(
        ["git", "rev-parse", "--path-format=absolute", "--git-common-dir"], text=True, timeout=30
    ).strip()
    return Path(common) / "hooks" / "pre-push"


def replace_hook(path: Path, expected: str, *, restore: bool = False) -> tuple[str, str]:
    details = path.lstat()
    if not stat.S_ISREG(details.st_mode) or not details.st_mode & stat.S_IXUSR:
        raise ValueError("The pre-push hook must be an executable regular file.")
    before = path.read_bytes()
    before_sha = hashlib.sha256(before).hexdigest()
    if before_sha != expected:
        raise ValueError("The pre-push hook differs from the reviewed hash.")
    original = stock_source(before.decode("utf-8"))
    after = (original if restore else original.replace(RUN, CAPTURE)).encode("utf-8")
    if after != before:
        with tempfile.NamedTemporaryFile(prefix=".pre-push.", dir=path.parent, delete=False) as stream:
            temporary = Path(stream.name)
        try:
            temporary.write_bytes(after)
            temporary.chmod(stat.S_IMODE(details.st_mode))
            if path.read_bytes() != before:
                raise ValueError("The pre-push hook changed during installation.")
            os.replace(temporary, path)
        finally:
            temporary.unlink(missing_ok=True)
    return before_sha, hashlib.sha256(after).hexdigest()


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--expect-sha256", required=True)
    parser.add_argument("--restore", action="store_true")
    args = parser.parse_args()
    try:
        before, after = replace_hook(hook_path(), args.expect_sha256, restore=args.restore)
    except (OSError, ValueError, subprocess.SubprocessError) as error:
        raise SystemExit(str(error)) from None
    print(f"pre_push_before_sha256={before}\npre_push_after_sha256={after}")


if __name__ == "__main__":
    main()
